class Solution {
public:
    int numberOfWays(string corridor) {
        const int MOD = 1e9 + 7;
        vector<int> seats;
        for (int i = 0; i < (int)corridor.size(); i++) {
            if (corridor[i] == 'S') seats.push_back(i);
        }
        if (seats.empty() || seats.size() % 2 != 0) return 0;
        long long ans = 1;
        for (int i = 1; i + 1 < (int)seats.size(); i += 2) {
            ans = (ans * (seats[i + 1] - seats[i])) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int numberOfWays(String corridor) {
        final int MOD = 1_000_000_007;
        List<Integer> seats = new ArrayList<>();
        for (int i = 0; i < corridor.length(); i++) {
            if (corridor.charAt(i) == 'S') seats.add(i);
        }
        if (seats.isEmpty() || seats.size() % 2 != 0) return 0;
        long ans = 1;
        for (int i = 1; i + 1 < seats.size(); i += 2) {
            ans = (ans * (seats.get(i + 1) - seats.get(i))) % MOD;
        }
        return (int) ans;
    }
}

var numberOfWays = function(corridor) {
    const MOD = 1000000007;
    const seats = [];
    for (let i = 0; i < corridor.length; i++) {
        if (corridor[i] === 'S') seats.push(i);
    }
    if (seats.length === 0 || seats.length % 2 !== 0) return 0;
    let ans = 1n;
    for (let i = 1; i + 1 < seats.length; i += 2) {
        ans = (ans * BigInt(seats[i + 1] - seats[i])) % BigInt(MOD);
    }
    return Number(ans);
};
